5: type DismissBehavior = 'close' | 'closeSilent' | 'none';
6: 
7: export interface MenuItem {
8:   id: string;
9:   label: string;
10:   description?: string;
11:   section: string;
12:   disabled?: boolean;
13:   filterOnly?: boolean;
14:   /** Match only the first word of the filter text (e.g. "/btw <question>" → match on "btw") */
15:   matchFirstToken?: boolean;
16:   trailing?: React.ReactNode;
17:   dismissBehavior?: DismissBehavior;
18:   onClick?: () => void;
19: }
20: 
21: export interface MenuSections {
22:   context: MenuItem[];
23:   model: MenuItem[];
24:   customize: MenuItem[];
25:   slash: MenuItem[];
26:   settings: MenuItem[];
27:   support: MenuItem[];
28: }
