30: interface BuildMenuItemsParams {
31:   slashCommands: string[];
32:   registry: FeatureRegistry;
33:   localFeatures?: Feature[];
34:   compose: { executeSlashCommand: (cmd: string) => void };
35: }
36: 
37: const byOrder = (a: Feature, b: Feature) =>
38:   (a.order ?? Number.POSITIVE_INFINITY) - (b.order ?? Number.POSITIVE_INFINITY);
39: 
40: function resolveDismissBehavior(f: Feature): DismissBehavior {
41:   if (f.state?.kind === 'toggle') return 'none';
42:   if (f.ui?.closeSilent) return 'closeSilent';
43:   return 'close';
44: }
45: 
46: function featureToMenuItem(f: Feature): MenuItem {
47:   return {
48:     id: f.id,
49:     label: f.label,
50:     description: f.description,
51:     section: f.section,
52:     disabled: f.disabled,
53:     filterOnly: f.ui?.filterOnly,
54:     matchFirstToken: f.ui?.matchFirstToken,
55:     trailing: renderMenuTrailing(f.state, { featureId: f.id }),
56:     dismissBehavior: resolveDismissBehavior(f),
57:     onClick: () => f.execute(),
58:   };
59: }
60: 
61: function buildSection(features: Feature[], section: FeatureSection): MenuItem[] {
62:   return features
63:     .filter((f) => f.section === section)
64:     .sort(byOrder)
65:     .map((f) => featureToMenuItem(f));
